function friendlyHttp(status,d,isJson,path){if(d&&d.error)return cleanDisplayMessage(`${d.error}${d.requestId?` (ref ${d.requestId})`:''}`);if(!isJson&&native()&&!API)return `${APK_NO_API} Request failed (${status}).`;if(!isJson)return `The service returned an unexpected response for ${path} (HTTP ${status}). Check service logs or retry shortly.`;if(status===401)return 'Your session is missing or expired. Sign in again.';if(status===404)return `This feature is unavailable in the current service version (${path}). Update the app or retry after deployment.`;if(status===405)return `This request is not supported by the current service (${path}).`;if(status>=500)return `PotHub encountered a server error (HTTP ${status}). Use the reference ID when checking service logs.`;return `Request to ${path} failed with HTTP ${status}.`;}
function friendlyNetwork(e,path,timeoutMs){if(e?.name==='AbortError')return `Request timed out after ${Math.round(timeoutMs/1000)}s (${path}). Check your connection and retry.`;if(native()&&!API)return `${APK_NO_API} Request: ${path}.`;return `Could not reach the PotHub service for ${path} (${cleanDisplayMessage(e?.message||'network error')}). Check your internet connection and retry.`}
async function api(path,opts={}){const {timeoutMs:requestTimeout=25000,noRetry=false,idempotencyKey,...fetchOptions}=opts,method=String(fetchOptions.method||'GET').toUpperCase(),retryable=!noRetry&&(['GET','HEAD'].includes(method)||!!idempotencyKey);let attempt=0,sessionRefreshed=false;while(true){const ctrl=new AbortController(),t=setTimeout(()=>ctrl.abort(),requestTimeout);try{const headers={'Content-Type':'application/json',...((nativeSessionToken||webSessionToken)?{Authorization:`Bearer ${nativeSessionToken||webSessionToken}`}:{}),...(fetchOptions.headers||{})};if(idempotencyKey)headers['Idempotency-Key']=idempotencyKey;const r=await fetch(`${API}${path}`,{credentials:'include',...fetchOptions,headers,signal:ctrl.signal});const isJson=(r.headers.get('content-type')||'').includes('application/json');const d=isJson?await r.json().catch(()=>({})):{};if(r.status===401&&!sessionRefreshed&&firebaseSessionActive&&firebaseAuth?.currentUser&&path!=='/api/auth/firebase-exchange'){sessionRefreshed=true;webSessionToken='';try{await exchangeFirebaseSession(firebaseAuth.currentUser);continue}catch{}}if(!r.ok)throw Object.assign(new Error(friendlyHttp(r.status,d,isJson,path)),{status:r.status,code:d.code||`HTTP_${r.status}`,requestId:d.requestId||r.headers.get('x-request-id')||null});return d;}catch(e){if(retryable&&attempt<1&&(!e.status||e.status>=500)){await new Promise(r=>setTimeout(r,180));attempt++;continue}if(e.status)throw e;throw Object.assign(new Error(friendlyNetwork(e,path,requestTimeout)),{code:e.name==='AbortError'?'TIMEOUT':'NETWORK'})}finally{clearTimeout(t)}}}

async function exchangeFirebaseSession(firebaseUser){const idToken=await firebaseUser.getIdToken();const exchanged=await api('/api/auth/firebase-exchange',{method:'POST',body:JSON.stringify({idToken}),timeoutMs:15000,noRetry:true});if(!exchanged.session)throw Error('Google sign-in did not return a Pothub session.');webSessionToken=exchanged.session;googleIdToken='';firebaseSessionActive=true;try{sessionStorage.setItem('pothub-session-v1',webSessionToken);sessionStorage.setItem('pothub-auth-provider-v1','google')}catch{}return exchanged}



let googleRedirectPromise=null;
let browserTicketPromise=null;
let browserTicketValue='';
// Only consume Firebase's redirect result when this tab explicitly initiated the
// Google redirect fallback. Without this guard, an old Firebase redirect result can
// be replayed during a later Developer/GitHub visit and switch workspaces unexpectedly.
const GOOGLE_REDIRECT_PENDING='pothub-google-redirect-pending-v1';
const GOOGLE_REDIRECT_MARKER='pothub_google_redirect';
function markGoogleRedirectPending(){try{sessionStorage.setItem(GOOGLE_REDIRECT_PENDING,'1')}catch{}}
function clearGoogleRedirectPending(){try{sessionStorage.removeItem(GOOGLE_REDIRECT_PENDING)}catch{}}
function isGoogleRedirectPending(){try{return sessionStorage.getItem(GOOGLE_REDIRECT_PENDING)==='1'}catch{return false}}
function setGoogleRedirectMarker(enabled){try{const url=new URL(location.href);if(enabled)url.searchParams.set(GOOGLE_REDIRECT_MARKER,'1');else url.searchParams.delete(GOOGLE_REDIRECT_MARKER);window.history.replaceState({},'',url.pathname+url.search+url.hash)}catch{}}
function isGoogleRedirectReturn(){try{return new URL(location.href).searchParams.get(GOOGLE_REDIRECT_MARKER)==='1'}catch{return false}}
function clearGoogleRedirectState(){clearGoogleRedirectPending();setGoogleRedirectMarker(false)}
function consumeGoogleRedirect(){if(!isGoogleRedirectPending()||!isGoogleRedirectReturn()){if(isGoogleRedirectPending())clearGoogleRedirectState();return Promise.resolve(null)}if(!googleRedirectPromise){googleRedirectPromise=getRedirectResult(firebaseAuth).then(async result=>{clearGoogleRedirectState();const user=result?.user||firebaseAuth?.currentUser;if(!user)return null;const me=await exchangeFirebaseSession(user);if(!me.user)throw Error('Google sign-in succeeded, but Pothub could not verify the Creator account.');return {...me,authProvider:'google'}}).catch(e=>{clearGoogleRedirectState();throw e})}return googleRedirectPromise}
// React StrictMode may clean up the first startup effect while the one-time ticket exchange is in flight.
// Keep the promise at module scope so a second effect run awaits the same result.
function consumeBrowserTicket(ticket){if(!browserTicketPromise||browserTicketValue!==ticket){browserTicketValue=ticket;browserTicketPromise=api('/api/auth/browser-exchange',{method:'POST',body:JSON.stringify({ticket}),timeoutMs:15000,noRetry:true}).then(exchanged=>{webSessionToken=exchanged.session||'';firebaseSessionActive=false;try{sessionStorage.removeItem('pothub-auth-provider-v1')}catch{}if(!webSessionToken)throw Error('GitHub sign-in returned no session. Please try Developer sign-in again.');try{sessionStorage.setItem('pothub-session-v1',webSessionToken)}catch{}return exchanged})}return browserTicketPromise}

