function flattenSelectOptions(children){
  const out=[];
  React.Children.forEach(children,child=>{
    if(!React.isValidElement(child))return;
    if(child.type===React.Fragment)out.push(...flattenSelectOptions(child.props.children));
    else if(child.type==='option')out.push(child);
  });
  return out;
}
function CustomSelect({value='',onChange,children,className='',style,disabled=false,'aria-label':ariaLabel,id,name}){
  const [open,setOpen]=useState(false),[active,setActive]=useState(0);
  const root=useRef(null),trigger=useRef(null),optionRefs=useRef([]);
  const options=flattenSelectOptions(children);
  const current=String(value??'');
  const selected=options.find(o=>String(o.props.value??o.props.children??'')===current);
  const textOf=o=>typeof o.props.children==='string'||typeof o.props.children==='number'?String(o.props.children):React.Children.toArray(o.props.children).map(x=>typeof x==='string'||typeof x==='number'?String(x):'').join('');
  useEffect(()=>{if(!open)return;const outside=e=>{if(!root.current?.contains(e.target))setOpen(false)};const key=e=>{if(e.key==='Escape'){setOpen(false);trigger.current?.focus()}};document.addEventListener('pointerdown',outside);document.addEventListener('keydown',key);return()=>{document.removeEventListener('pointerdown',outside);document.removeEventListener('keydown',key)}},[open]);
  useEffect(()=>{if(open){const idx=Math.max(0,options.findIndex(o=>String(o.props.value??textOf(o))===current));setActive(idx);requestAnimationFrame(()=>optionRefs.current[idx]?.scrollIntoView({block:'nearest'}))}},[open,current,options.length]);
  const choose=o=>{if(!o||o.props.disabled)return;const next=String(o.props.value??textOf(o));onChange?.({target:{value:next,name}});setOpen(false);trigger.current?.focus()};
  const keyDown=e=>{if(disabled)return;if((e.key==='ArrowDown'||e.key==='ArrowUp')&&!options.length){e.preventDefault();return}if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if(!open){setOpen(true);return}setActive(i=>(i+(e.key==='ArrowDown'?1:-1)+options.length)%options.length)}else if(e.key==='Enter'||e.key===' '){e.preventDefault();if(open)choose(options[active]);else setOpen(true)}else if(e.key==='Home'&&open){e.preventDefault();setActive(0)}else if(e.key==='End'&&open){e.preventDefault();setActive(Math.max(0,options.length-1))}}
  return <div ref={root} className={`custom-select ${open?'is-open':''} ${className}`} style={style} data-disabled={disabled?'true':'false'}>
    <button ref={trigger} id={id} type="button" className="custom-select-trigger" role="combobox" aria-label={ariaLabel} aria-haspopup="listbox" aria-expanded={open} disabled={disabled} onClick={()=>setOpen(v=>!v)} onKeyDown={keyDown}>
      <span className={`custom-select-value ${selected?'':'placeholder'}`}>{selected?textOf(selected):'Choose an option'}</span><svg className="custom-select-chevron" viewBox="0 0 24 24" aria-hidden="true"><path d="m6 9 6 6 6-6" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/></svg>
    </button>
    {open&&<div className="custom-select-menu" role="listbox" aria-label={ariaLabel||'Options'}>{options.map((o,i)=>{const v=String(o.props.value??textOf(o)),isSelected=v===current;return <button ref={el=>optionRefs.current[i]=el} type="button" role="option" aria-selected={isSelected} key={o.key||`${v}-${i}`} disabled={o.props.disabled} className={`custom-select-option ${isSelected?'selected':''}`} onMouseEnter={()=>setActive(i)} onClick={()=>choose(o)}><span>{textOf(o)}</span>{isSelected&&<span className="custom-select-check" aria-hidden="true">✓</span>}</button>})}{!options.length&&<div className="custom-select-empty">No options available</div>}</div>}
  </div>;
}

