const repoLoadLock=useRef(false);
async function loadRepos(){
 if(repoLoadLock.current)return;
 repoLoadLock.current=true;setBusy('repos');setRepoLoadError('');setRepoReconnectRequired(false);
 const cacheKey=`github-repositories:${String(user?.id||'')}`;
 try{
  // Paint the last successful account-specific list immediately, then refresh in background.
  try{const cached=await db.settings.get(cacheKey);if(Array.isArray(cached?.value)&&cached.value.length){setRepos(cached.value);}}
  catch{}
  const d=await api('/api/github/repos',{timeoutMs:25000,noRetry:true});
  const rows=Array.isArray(d.repos)?d.repos:[];
  setRepos(rows);
  try{await db.settings.put({key:cacheKey,value:rows,updatedAt:Date.now()})}catch{}
  setRepoReconnectRequired(false);
  if(!rows.length){setRepoLoadError(d.note||'GitHub returned no repositories. Check repository permissions and organization access.')}
  else if(repo&&!rows.some(r=>r.full_name===repo.full_name))setRepo(null);
 }catch(e){
  const message=String(e?.message||'Repository discovery failed.');
  const needsReconnect=!!(e?.reconnect||e?.status===401||/authorization does not include repository access|account changed|connection has expired|SSO authorization/i.test(message));
  setRepoReconnectRequired(needsReconnect);
  setRepoLoadError(repos.length&&!needsReconnect?`Refresh failed. Your saved list (${repos.length}) is still available.`:message);
  if(needsReconnect)setRepos([]);
 }finally{repoLoadLock.current=false;setBusy('')}
}
